from collections import OrderedDict
from moler.helpers import convert_to_number
import re


class RtgConfigConverter:
    def __init__(self, config):
        if isinstance(config, dict):
            self._config_dict = config
            self._config_string = None
        else:
            self._config_dict = None
            self._config_string = config

    @property
    def config_string(self):
        if self._config_string is None:
            self.get_config_string()
        return self._config_string

    @property
    def config_dict(self):
        if self._config_dict is None:
            self.get_config_dict()
        return self._config_dict

    def get_config_string(self):
        """Get configuration as string like in config file.

        :return: Configuration as string
        """
        self._config_string = ''
        for section in self.config_dict:
            self._write_section(section)
        return self._config_string

    def _write_section(self, section):
        """Write one section to configuration string.

        :param section: Section name
        :return: None
        """
        already_section_head = False
        for key in self.config_dict[section]:
            if isinstance(self.config_dict.get(section).get(key), dict):
                self._write_section_with_number(section, number=key)
            else:
                if not already_section_head:
                    self._config_string += '[{}]\n'.format(section)
                    already_section_head = True
                self._config_string += '{} = {}\n'.format(key, self.config_dict[section][key])
        self._config_string += '\n'

    def _write_section_with_number(self, section, number):
        """Write section with number to configuration string.

        :param section: Section name
        :param number: Number of device in section
        :return: None
        """
        self._config_string += '[{}_{}]\n'.format(section, number)
        for k in self.config_dict[section][number]:
            self._config_string += '{} = {}\n'.format(k, self.config_dict[section][number][k])
        if int(number) < len(self.config_dict[section]):
            self._config_string += '\n'

    def get_config_dict(self):
        """Get configuration as dictionary.

        :return: Configuration as dictionary
        """
        lines = self.config_string.splitlines()
        re_section_with_number = re.compile(r'^\[(?P<SECTION>.+?)_(?P<NUMBER>\d+)\]$')
        re_section_without_number = re.compile(r'^\[(?P<SECTION>.+[^\d])\]$')
        re_config_line = re.compile(r'^(?P<KEY>[^;].+?)\s*=\s*(?P<VALUE>.*)')

        self._config_dict = OrderedDict()
        section = None
        number = None
        for line in lines:
            if re.search(re_section_with_number, line):
                section_with_number = re.search(re_section_with_number, line)
                section = section_with_number.group('SECTION')
                number = section_with_number.group('NUMBER')

            elif re.search(re_section_without_number, line):
                section_without_number = re.search(re_section_without_number, line)
                section = section_without_number.group('SECTION')
                number = None

            elif re.search(re_config_line, line):
                config_line = re.search(re_config_line, line)
                self._add_config_item(config_line, section, number)

        return self._config_dict

    def _add_config_item(self, config_line, section, number):
        """Parse and add line with configuration item to configuration dictionary.

        :param config_line: Line with config item
        :param section: Name of section
        :param number: Number of device in section or None
        :return: None
        """
        key = config_line.group('KEY')
        value = config_line.group('VALUE')
        if number:
            self._config_dict.setdefault(section, OrderedDict()).setdefault(number, OrderedDict())[key] = \
                convert_to_number(value)
        else:
            self._config_dict.setdefault(section, OrderedDict())[key] = convert_to_number(value)

    @staticmethod
    def dict_merge(dct, merge_dct):
        """ Recursive dict merge. Update not only top level keys but also nested dictionaries.

        :param dct: dict onto which the merge is executed
        :param merge_dct: dct merged into dct
        :return: None
        """
        for k, v in merge_dct.iteritems():
            if k in dct and isinstance(dct[k], dict) and isinstance(merge_dct[k], dict):
                RtgConfigConverter.dict_merge(dct[k], merge_dct[k])
            else:
                dct[k] = merge_dct[k]
        return dct
